fn check_all_lowercase(v: &Vec<char>) -> bool {
    // Return false if empty
    if v.is_empty() {
        return false;
    }
    // Check all chars are between 'a' and 'z'
    v.iter().all(|&c| c >= 'a' && c <= 'z')
}

